export type Region = string;

/** Request body to create a new rollout for a scheduler-backed application. */
export type ContainersCreateApplicationRolloutRequest = {
	/** Description of the rollout process. */
	description: string;
	/**
	 * Kind of the rollout process. Defaults to "full_auto".
	 *  - "full_auto": For rolling rollouts, starts progressing steps upon rollout creation. For new_instances rollouts, advances percentage targets automatically after target-version health is observed.
	 *  - "full_manual": Requires manually progressing each step in the rollout using the UpdateRollout's action parameter.
	 */
	kind?: "full_auto" | "full_manual";
	/**
	 * Initial target version percentage (0-100). Version sync actively replaces instances to match.
	 * Required when strategy is "new_instances" and kind is "full_manual". When strategy is "new_instances" and kind is "full_auto", omitted percentage starts at 10% or the smallest percentage that targets at least one instance. Unused for "rolling".
	 */
	percentage?: number;
	/**
	 * Percentage of rollout to increase in each step when "steps" is absent. Applicable values: 5, 10, 20, 25, 50, 100.
	 * These create rollouts with 20, 10, 5, 4, 2, 1 steps respectively.
	 * Only valid for "rolling" strategy.
	 */
	step_percentage?: 5 | 10 | 20 | 25 | 50 | 100;
	/**
	 * Steps defining the rollout process, used when "step_percentage" is absent.
	 * Specify only one of "step_percentage" or "steps" when creating a rollout.
	 * "steps" allow granular control over each step.
	 * Only valid for "rolling" strategy.
	 */
	steps?: RolloutStepRequest[];
	/**
	 * Strategy used for the rollout.
	 * - "rolling": Step-based rollout with health gates. Actively replaces instances to reach each step's target percentage.
	 * - "new_instances": Percentage control over version distribution. Version sync actively replaces instances to match the configured percentage. The "full_auto" kind advances through fixed percentage targets after target-version health is observed.
	 */
	strategy: "rolling" | "new_instances";
	/** User-specified container configuration changes. */
	target_configuration: ModifyUserDeploymentConfiguration;
};

/** Restricts placement to datacenters in the selected jurisdiction. Choose "eu", "fedramp", or "us". When combined with regions, EU supports EEUR and WEUR while FedRAMP and US support ENAM and WNAM. */
export type ApplicationJurisdiction = string;

/** Result of deleting an image registry from a Containers account. */
export type ContainersDeleteImageRegistryResponseBody = {
	domain: Domain;
};

/** Result of starting asynchronous deletion for a Containers application. */
export type ContainersDeleteApplicationResponseBody = {
	message: string;
};

/** Set of properties to configure a Durable Object-backed application. */
export type DurableObjectsConfiguration = DurableObjectsConfigurationNamespaceId | DurableObjectsConfigurationScriptAndClass;

/** Settings for deployment observability such as logging. */
export type DeploymentObservability = {
	/** Observability logging settings. */
	logs?: ObservabilityLogs;
};

/** Shows a count of application instance states. */
export type ApplicationHealthInstances = {
	/** Number of instances whose runtime reports the container as running (container_status = "running"). This is a subset of the placements that remain up: an instance that is already bound to a Durable Object and serving traffic is counted under "assigned" until its container_status catches up to "running", so container_status can briefly lag Durable Object attachment under churn. To estimate running, Durable-Object-bound instances, sum "active" + "assigned" rather than reading "active" alone. */
	active: number;
	/** Number of instances bound to a Durable Object with a running placement whose container_status remains behind "running". These count as live, serving instances; "active" + "assigned" approximates the running, Durable-Object-bound count. */
	assigned: number;
};

/** Specifies the configuration for the image registry credential to create. Cloudflare requires both fields for managed registries. For external registries, Cloudflare ignores both fields, and the registry provider determines the returned credentials' permissions and lifetime. */
export type ImageRegistryCredentialsConfiguration = {
	/** The number of minutes Cloudflare managed registry credentials stay valid. Required for managed registries and must remain positive. Cloudflare ignores this value for external registries. */
	expiration_minutes?: number;
	/** The permissions for Cloudflare managed registry credentials. Required for managed registries. Cloudflare ignores this value for external registries. */
	permissions?: ImageRegistryPermissions[];
};

/** Specifies what permissions the credentials carry. */
export type ImageRegistryPermissions = "pull" | "push" | "list";

/** Steps defining the rollout process. */
export type RolloutStepRequest = {
	/** Description of the rollout step. */
	description: string;
	step_size: {
		/** Percentage of instances affected in this step. Min 10% and Max 100%. */
		percentage: number;
	};
};

/** Steps within the rollout process. */
export type RolloutStep = {
	/** UTC timestamp string in ISO 8601 format. */
	completed_at?: ISO8601Timestamp;
	/** Description of the rollout step. */
	description: string;
	/** The sequential order of the rollout step, automatically assigned starting from 1, based on the total number of steps in the rollout process. */
	id: number;
	/** Reason for the step's current status. */
	reason?: string;
	/** UTC timestamp string in ISO 8601 format. */
	started_at?: ISO8601Timestamp;
	/** Status of the rollout step. */
	status: "pending" | "progressing" | "reverting" | "completed" | "reverted";
	step_size: {
		/** Percentage of instances affected in this step. Min 10% and Max 100%. */
		percentage: number;
	};
};

/** The Containers scheduler manages this application's instances, configuration, versions, and rollouts. */
export type ScheduledApplication = Application & {
	/**
	 * Selects a scheduler-backed application. Use `default` when the Containers
	 * scheduler should maintain the requested number of instances and manage deployment
	 * configuration, placement, scaling, versions, and rollouts.
	 */
	scheduling_policy: ScheduledApplicationSchedulingPolicy;
};

/** The application name. */
export type ApplicationName = string;

/** The current lifecycle state of a container instance. */
export type ContainerInstanceStatusState = "provisioning" | "running" | "failed" | "stopping" | "stopped" | "unhealthy" | "inactive" | "unknown";

/** The last-reported state of a logical container instance. */
export type ContainerInstanceBase = {
	/** An Application ID represents an identifier of an application. */
	application_id?: ApplicationID;
	/** The resources allocated to the container instance. */
	configuration?: ContainerInstanceConfiguration;
	/** A container instance ID (64-character hex Durable Object actor ID). */
	id: ContainerInstanceID;
	/** The image for the current container placement, when one is available. */
	image?: Image;
	/** The location of the instance's current container placement. */
	location?: ContainerInstanceLocation;
	/** The customer-provided instance name, when available. Its UTF-8 encoding uses at most 1,024 bytes. */
	name?: string;
	/** The time at which the current container placement started, when one exists. */
	started_at?: ISO8601Timestamp;
	/** The latest known status of a container instance. */
	status: ContainerInstanceStatus;
};

/** The latest known status of a container instance. */
export type ContainerInstanceStatus = {
	/** The process exit code, when the runtime reports one. */
	exit_code?: number;
	/** The current lifecycle state of a container instance. */
	state: ContainerInstanceStatusState;
	/** UTC timestamp string in ISO 8601 format. */
	updated_at: ISO8601Timestamp;
};

/** The location of the instance's current container placement. */
export type ContainerInstanceLocation = {
	/** Unique location code used to identify locations on a logical level. */
	name: LocationID;
	/** Represents a group of datacenters. Choose one of "AFR", "APAC", "EEUR", "ENAM", "WNAM", "ME", "OC", "SAM", or "WEUR". */
	region: Region;
};

/** The public Containers API returns a list of applications. */
export type ContainersListApplications = ContainersApplicationResponse[];

/** The public Containers API returns an application. */
export type ContainersApplicationResponse = ScheduledApplication | DurableObjectApplication;

/** The resources allocated to the container instance. */
export type ContainerInstanceConfiguration = {
	/** Disk allocated to the container instance, in decimal MB. */
	disk: number;
	/** Memory allocated to the container instance, in MiB. */
	memory: number;
	/** Number of virtual CPUs allocated to the container instance. */
	vcpu: number;
};

/** The scheduling policy to use for an application. */
export type SchedulingPolicy = "default" | "durable_object";

/** The type of external registry that is being configured. */
export type ExternalRegistryKind = "ECR" | "DockerHub" | "GAR";

/** UTC timestamp string in ISO 8601 format. */
export type ISO8601Timestamp = string;

/** Unique location code used to identify locations on a logical level. */
export type LocationID = string;

/** User-provided SSH public key. */
export type UserSSHPublicKey = {
	/** Optional human readable name for this key. */
	name?: string;
	/** An SSH public key. */
	public_key: SSHPublicKey;
};

/** User-specified container configuration changes. */
export type ModifyUserDeploymentConfiguration = {
	authorized_keys?: UserSSHPublicKey[];
	/**
	 * The command that runs when the container starts, passed to the entrypoint.
	 * You can override this at run-time. If you override only the command,
	 * it gets passed to the default entrypoint specified in the image.
	 */
	command?: Command;
	/**
	 * The entry point for the container, specifying the executable to run when the container starts.
	 * You can override this at run-time. If you do, the default command from the image is ignored.
	 * Specify both entrypoint and command at run-time to completely replace the image defaults.
	 */
	entrypoint?: Entrypoint;
	/** Container environment variables. */
	environment_variables?: EnvironmentVariable[];
	/** Image url. */
	image?: Image;
	/**
	 * The instance type configures vCPU, memory, and disk.
	 *
	 * - "lite": 1/16 vCPU, 256 MiB memory, 2 GB disk
	 * - "basic": 1/4 vCPU, 1 GiB memory, 4 GB disk
	 * - "standard-1": 1/2 vCPU, 4 GiB memory, 8 GB disk
	 * - "standard-2": 1 vCPU, 6 GiB memory, 12 GB disk
	 * - "standard-3": 2 vCPU, 8 GiB memory, 16 GB disk
	 * - "standard-4": 4 vCPU, 12 GiB memory, 20 GB disk
	 */
	instance_type?: InstanceType;
	/** Settings for deployment observability such as logging. */
	observability?: DeploymentObservability;
};

/** User-specified container configuration. */
export type UserDeploymentConfiguration = {
	authorized_keys?: UserSSHPublicKey[];
	/**
	 * The command that runs when the container starts, passed to the entrypoint.
	 * You can override this at run-time. If you override only the command,
	 * it gets passed to the default entrypoint specified in the image.
	 */
	command?: Command;
	/**
	 * The entry point for the container, specifying the executable to run when the container starts.
	 * You can override this at run-time. If you do, the default command from the image is ignored.
	 * Specify both entrypoint and command at run-time to completely replace the image defaults.
	 */
	entrypoint?: Entrypoint;
	/** Container environment variables. */
	environment_variables?: EnvironmentVariable[];
	/** Image url. */
	image: Image;
	/**
	 * The instance type configures vCPU, memory, and disk.
	 *
	 * - "lite": 1/16 vCPU, 256 MiB memory, 2 GB disk
	 * - "basic": 1/4 vCPU, 1 GiB memory, 4 GB disk
	 * - "standard-1": 1/2 vCPU, 4 GiB memory, 8 GB disk
	 * - "standard-2": 1 vCPU, 6 GiB memory, 12 GB disk
	 * - "standard-3": 2 vCPU, 8 GiB memory, 16 GB disk
	 * - "standard-4": 4 vCPU, 12 GiB memory, 20 GB disk
	 */
	instance_type?: InstanceType;
	/** Settings for deployment observability such as logging. */
	observability?: DeploymentObservability;
};

export type ApplicationConstraints = {
	/** Restricts placement to datacenters in the selected jurisdiction. Choose "eu", "fedramp", or "us". When combined with regions, EU supports EEUR and WEUR while FedRAMP and US support ENAM and WNAM. */
	jurisdiction?: ApplicationJurisdiction;
	regions?: Region[];
};

export type ApplicationHealth = {
	errors: ApplicationHealthErrors;
	/** Shows a count of application instance states. */
	instances: ApplicationHealthInstances;
	/**
	 * High-level health assessment. Only populated for "new_instances" strategy.
	 * Based on a sample of target-version instances rather than a full count.
	 * - "pending": Zero target-version instances exist yet.
	 * - "healthy": Every sampled target-version instance reports running or active.
	 * - "degraded": Some sampled instances remain starting or scheduling.
	 * - "unhealthy": One or more sampled instances have failed.
	 */
	summary?: "healthy" | "degraded" | "unhealthy" | "pending";
};

export type ApplicationHealthError = {
	/** An event within a Placement or a Job. */
	event: PlacementEvent;
	/** An instance ID represents an identifier of an instance configuration that maintains an underlying placement. */
	instance_id: InstanceID;
};

export type ApplicationHealthErrors = ApplicationHealthError[];

export type DefaultImageRegistryKind = "default";

export type EventType = "Info" | "Error" | "Warn" | "UserError" | "SystemError";

export type ExecFormParam = string;
